# Lei 8.112/90 — lote L2, parte a (provimento, posse, exercício, estágio, vacância, remoção). Tupla: (ponto,[átomos],g,padrao,dif,enunciado,comentário,tipo_erro,tag_par,extra)
CJ = {"fonte": {"tipo": "doutrina", "ref": "CF, art. 41 (EC 19/1998); STF e STJ", "conferida": "conhecimento"}, "risco": ["vigencia_superada_no_texto"]}
Q = [
# P01
("P01",["2","3"],"C","conceito_correto",1,"Nos termos da Lei n.º 8.112/1990, servidor é a pessoa legalmente investida em cargo público, o qual consiste no conjunto de atribuições e responsabilidades previstas na estrutura organizacional que devem ser cometidas a um servidor.","Arts. 2º e 3º.","","p01a",{}),
("P01",["2","3"],"E","confusao_instituto",1,"Nos termos da Lei n.º 8.112/1990, servidor é a pessoa que mantém vínculo funcional com a Administração, ainda que não investida em cargo público, e cargo público é a pessoa jurídica criada por lei para exercer atribuições públicas.","Art. 2º: servidor é a pessoa legalmente investida em cargo público; art. 3º: cargo é o conjunto de atribuições e responsabilidades, não uma pessoa jurídica.","amplia conceito de servidor","p01a",{}),
("P01",["3"],"C","conceito_correto",2,"Os cargos públicos federais são criados por lei, com denominação própria e vencimento pago pelos cofres públicos, e podem ser providos em caráter efetivo ou em comissão.","Art. 3º, parágrafo único.","","p01b",{}),
("P01",["3"],"E","troca_autoridade",2,"Os cargos públicos federais são criados por decreto do Presidente da República, com denominação própria e vencimento pago pelos cofres públicos, para provimento em caráter efetivo ou em comissão.","Art. 3º, parágrafo único: os cargos são criados por lei (e não por decreto).","troca lei por decreto","p01b",{}),
("P01",["4"],"C","conceito_correto",1,"Salvo nos casos previstos em lei, é proibida a prestação de serviços gratuitos à Administração Pública federal por servidor.","Art. 4º.","","p01c",{}),
("P01",["4"],"E","excecao_omitida",1,"A prestação de serviços gratuitos ao serviço público é absolutamente vedada, não havendo hipótese legal que a autorize.","Art. 4º: a proibição admite exceção, nos casos previstos em lei.","nega a exceção legal","p01c",{}),
("P01",["5"],"C","conceito_correto",2,"Entre os requisitos básicos para investidura em cargo público estão a nacionalidade brasileira, o gozo dos direitos políticos, a quitação com as obrigações militares e eleitorais e a idade mínima de dezoito anos.","Art. 5º, I, II, III e V.","","p01d",{}),
("P01",["5"],"E","restricao_indevida",2,"Entre os requisitos básicos para investidura em cargo público estão a nacionalidade brasileira nata, o gozo dos direitos políticos, a quitação com as obrigações militares e eleitorais e a idade mínima de vinte e um anos.","Art. 5º, I e V: nacionalidade brasileira (nata ou naturalizada, salvo cargos privativos de brasileiro nato na CF) e idade mínima de dezoito anos.","altera requisitos","p01d",{}),
("P01",["5"],"C","troca_numero",2,"Às pessoas com deficiência é assegurado o direito de se inscrever em concurso para cargo cujas atribuições sejam compatíveis com a deficiência, sendo-lhes reservadas até 20% das vagas oferecidas no certame.","Art. 5º, § 2º.","","p01e",{}),
("P01",["5"],"E","troca_numero",2,"Às pessoas com deficiência é assegurado o direito de se inscrever em concurso para cargo cujas atribuições sejam compatíveis com a deficiência, sendo-lhes reservado no mínimo 20% das vagas oferecidas no certame.","Art. 5º, § 2º: reservam-se até 20% das vagas (limite máximo, não mínimo).","troca 'até' por 'no mínimo'","p01e",{}),
("P01",["5"],"C","excecao_omitida",3,"As universidades e instituições de pesquisa científica e tecnológica federais podem prover seus cargos com professores, técnicos e cientistas estrangeiros, na forma da Lei n.º 8.112/1990.","Art. 5º, § 3º.","","p01f",{}),
("P01",["5"],"E","generalizacao",3,"Por exigência da nacionalidade brasileira, nenhum cargo público federal pode ser provido por estrangeiro, nem mesmo em universidades e instituições federais de pesquisa científica.","Art. 5º, § 3º: universidades e instituições de pesquisa federais podem prover cargos com estrangeiros.","generaliza o requisito","p01f",{}),
# P02
("P02",["8"],"C","conceito_correto",1,"Constituem formas de provimento de cargo público federal a nomeação, a promoção, a readaptação, a reversão, o aproveitamento, a reintegração e a recondução.","Art. 8º, I, II e V a IX.","","p02a",{}),
("P02",["8"],"E","confusao_instituto",1,"A remoção e a redistribuição figuram, ao lado da nomeação, entre as formas de provimento de cargo público previstas na Lei n.º 8.112/1990.","Art. 8º: remoção e redistribuição são deslocamentos, não formas de provimento (arts. 36 e 37).","inclui deslocamentos no rol de provimento","p02a",{}),
("P02",["8"],"C","caso_concreto",2,"Servidor estável que seja reintegrado ao cargo anteriormente ocupado, depois de invalidada judicialmente a sua demissão, é provido no cargo por forma de provimento derivada expressamente listada no art. 8.º da Lei n.º 8.112/1990.","Art. 8º, VIII (reintegração).","","p02b",{}),
("P02",["8","33"],"E","confusao_instituto",2,"A exoneração a pedido de servidor estável, por ser ato que extingue o vínculo com o cargo e o devolve à Administração, é forma de provimento derivada expressamente listada no art. 8.º da Lei n.º 8.112/1990.","Exoneração é hipótese de vacância (art. 33, I), não de provimento.","confunde vacância com provimento","p02b",{}),
# P03
("P03",["9"],"C","conceito_correto",1,"A nomeação far-se-á em caráter efetivo, quando se tratar de cargo isolado de provimento efetivo ou de carreira, e em comissão, para cargos de confiança vagos.","Art. 9º, I e II.","","p03a",{}),
("P03",["9"],"E","troca_efeito",2,"O servidor ocupante de cargo em comissão pode ser nomeado para exercer interinamente outro cargo de confiança e, nessa hipótese, acumula as remunerações de ambos durante a interinidade.","Art. 9º, parágrafo único: deve optar pela remuneração de um deles durante a interinidade.","acumulação de remunerações","p03a",{}),
("P03",["10"],"C","conceito_correto",1,"A nomeação para cargo de carreira ou cargo isolado de provimento efetivo depende de prévia habilitação em concurso público de provas ou de provas e títulos, obedecidos a ordem de classificação e o prazo de validade do certame.","Art. 10.","","p03b",{}),
("P03",["10"],"E","excecao_omitida",2,"A nomeação para cargo de carreira ou cargo isolado de provimento efetivo depende de prévia habilitação em concurso público, mas a autoridade competente pode inverter a ordem de classificação, nomeando candidato de pior colocação, por conveniência do serviço, dentro do prazo de validade do certame.","Art. 10: a nomeação obedece à ordem de classificação e ao prazo de validade do concurso.","dispensa concurso","p03b",{}),
("P03",["12"],"C","troca_numero",2,"O concurso público terá validade de até dois anos, podendo ser prorrogado uma única vez, por igual período.","Art. 12, caput.","","p03c",{}),
("P03",["12"],"E","troca_numero",2,"O concurso público terá validade de até dois anos, podendo ser prorrogado por até duas vezes, por períodos iguais ao inicial.","Art. 12, caput: uma única vez, por igual período.","admite mais de uma prorrogação","p03c",{}),
("P03",["12"],"C","caso_concreto",3,"Enquanto houver candidato aprovado em concurso anterior com prazo de validade não expirado, não se abrirá novo concurso para o provimento dos mesmos cargos federais regidos pela Lei n.º 8.112/1990.","Art. 12, § 2º.","","p03d",{}),
("P03",["12"],"E","troca_efeito",3,"Mesmo havendo candidato aprovado em concurso anterior com prazo de validade em curso, a Administração pode abrir novo certame, desde que publique edital no Diário Oficial da União e em jornal diário de grande circulação.","Art. 12, § 2º: não se abrirá novo concurso enquanto houver candidato aprovado com prazo não expirado; a publicação é regra do § 1º, não afasta a vedação.","confunde publicidade com permissão","p03d",{}),
("P03",["12"],"C","conceito_correto",2,"O prazo de validade do concurso e as condições de sua realização serão fixados em edital, publicado no Diário Oficial da União e em jornal diário de grande circulação.","Art. 12, § 1º.","","p03e",{}),
("P03",["11"],"C","conceito_correto",2,"O concurso poderá ser de provas ou de provas e títulos, realizado em uma ou em duas etapas, conforme dispuserem a lei e o regulamento do respectivo plano de carreira.","Art. 11.","","p03f",{}),
("P03",["11"],"E","restricao_indevida",2,"O concurso será necessariamente de provas e títulos, realizado em uma única etapa, devendo o edital proibir a cobrança de qualquer valor de inscrição.","Art. 11: provas ou provas e títulos, em uma ou duas etapas; inscrição condicionada ao pagamento do valor fixado em edital quando indispensável ao custeio, ressalvadas as isenções.","impõe regra não prevista","p03f",{}),
# P04 Posse
("P04",["13"],"C","troca_numero",1,"A posse ocorrerá no prazo de trinta dias contados da publicação do ato de provimento.","Art. 13, § 1º.","","p04a",{}),
("P04",["13"],"E","troca_numero",1,"A posse ocorrerá no prazo de quinze dias contados da publicação do ato de provimento.","Art. 13, § 1º: trinta dias (quinze dias é o prazo do exercício, art. 15, § 1º).","confunde prazo da posse com o do exercício","p04a",{}),
("P04",["13"],"C","conceito_correto",2,"Só haverá posse nos casos de provimento de cargo por nomeação, e ela se dá mediante assinatura do termo, que não pode ter as atribuições, os deveres e os direitos alterados unilateralmente.","Art. 13, caput e § 4º.","","p04b",{}),
("P04",["13"],"E","generalizacao",2,"A posse é ato necessário a todas as formas de provimento de cargo público, inclusive a promoção e a reversão, e se aperfeiçoa pela assinatura do termo, no qual constarão as atribuições, os deveres e os direitos inerentes ao cargo.","Art. 13, § 4º: só há posse na nomeação.","estende posse a todo provimento","p04b",{}),
("P04",["13"],"C","caso_concreto",2,"Aprovado em concurso, Carlos foi nomeado, mas encontra-se em outro Estado e não poderá comparecer ao órgão no prazo da posse; nesse caso, ele poderá ser empossado por meio de procurador, desde que a procuração seja específica.","Art. 13, § 3º.","","p04c",{}),
("P04",["13"],"E","caso_concreto",2,"Aprovado em concurso, Carlos foi nomeado, mas encontra-se em outro Estado e não poderá comparecer ao órgão no prazo da posse; nesse caso, a posse por procuração é vedada, devendo o ato de provimento ser tornado sem efeito.","Art. 13, § 3º: a posse poderá dar-se mediante procuração específica.","veda procuração","p04c",{}),
("P04",["13"],"C","excecao_omitida",3,"Se, na data da publicação do ato de provimento, o servidor estiver em licença para tratamento de doença em pessoa da família (art. 81, I), o prazo de posse será contado do término do impedimento.","Art. 13, § 2º c/c art. 81, I.","","p04d",{}),
("P04",["13"],"E","excecao_omitida",3,"Ainda que o servidor esteja, na data da publicação do ato de provimento, em licença para tratamento de doença em pessoa da família, o prazo de posse corre normalmente a partir da publicação.","Art. 13, § 2º: nessas licenças e afastamentos, o prazo é contado do término do impedimento.","ignora a exceção do § 2º","p04d",{}),
("P04",["13"],"C","consequencia",2,"Será tornado sem efeito o ato de provimento se a posse não ocorrer no prazo legal.","Art. 13, § 6º.","","p04e",{}),
("P04",["13"],"E","consequencia",2,"Se a posse não ocorrer no prazo legal, o servidor será exonerado de ofício do cargo.","Art. 13, § 6º: o ato de provimento é tornado sem efeito; a exoneração de ofício se aplica a quem toma posse e não entra em exercício (art. 34, parágrafo único, II).","confunde consequências","p04e",{}),
("P04",["13","14"],"C","conceito_correto",2,"No ato da posse, o servidor apresentará declaração de bens e valores que constituem seu patrimônio e declaração quanto ao exercício ou não de outro cargo, emprego ou função pública, além de ter de ser julgado apto em inspeção médica oficial prévia.","Art. 13, § 5º; art. 14.","","p04f",{}),
("P04",["14"],"E","troca_efeito",2,"Na posse, o servidor apresentará declaração de bens e valores e declaração quanto ao exercício de outro cargo, emprego ou função pública, sendo a inspeção médica oficial exigida apenas ao final do estágio probatório, para fins de estabilidade.","Art. 14: a posse dependerá de prévia inspeção médica oficial; só pode ser empossado quem for julgado apto física e mentalmente.","dispensa inspeção prévia","p04f",{}),
# P05 Exercício
("P05",["15"],"C","troca_numero",1,"É de quinze dias o prazo para o servidor empossado em cargo público entrar em exercício, contados da data da posse.","Art. 15, § 1º.","","p05a",{}),
("P05",["15"],"E","troca_numero",1,"É de trinta dias o prazo para o servidor empossado em cargo público entrar em exercício, contados da publicação do ato de nomeação.","Art. 15, § 1º: quinze dias, contados da data da posse.","troca prazo e termo inicial","p05a",{}),
("P05",["15"],"C","consequencia",2,"O servidor que tomou posse e não entrou em exercício no prazo legal será exonerado do cargo.","Art. 15, § 2º; art. 34, parágrafo único, II.","","p05b",{}),
("P05",["15"],"E","consequencia",2,"O servidor que tomou posse, mas não entrou em exercício no prazo legal, terá tornado sem efeito o ato de provimento, sem exoneração.","Art. 15, § 2º: será exonerado (o ato de provimento tornado sem efeito é consequência da ausência de posse).","confunde consequências","p05b",{}),
("P05",["15"],"C","troca_autoridade",2,"Compete à autoridade competente do órgão ou entidade para onde for nomeado ou designado o servidor dar-lhe exercício.","Art. 15, § 3º.","","p05c",{}),
("P05",["15"],"E","troca_autoridade",2,"Compete à autoridade que expediu o ato de nomeação dar exercício ao servidor, ainda que o cargo esteja lotado em outro órgão.","Art. 15, § 3º: compete à autoridade do órgão ou entidade para onde for nomeado ou designado.","troca a autoridade","p05c",{}),
("P05",["15"],"C","excecao_omitida",3,"O início do exercício de função de confiança coincidirá com a data de publicação do ato de designação, salvo quando o servidor estiver em licença ou afastado, hipótese em que recairá no primeiro dia útil após o término do impedimento, que não poderá exceder a trinta dias da publicação.","Art. 15, § 4º.","","p05d",{}),
("P05",["18"],"C","troca_numero",2,"O servidor removido para outro município terá, no mínimo, dez e, no máximo, trinta dias, contados da publicação do ato, para retomar o efetivo desempenho das atribuições do cargo, incluído o tempo de deslocamento.","Art. 18, caput.","","p05e",{}),
("P05",["18"],"E","troca_numero",2,"O servidor removido para outro município terá, no mínimo, quinze e, no máximo, quarenta e cinco dias, contados da publicação do ato, para retomar o efetivo desempenho das atribuições do cargo, não se incluindo nesse prazo o tempo de deslocamento.","Art. 18: mínimo de 10 e máximo de 30 dias, incluído o tempo necessário para o deslocamento.","altera prazos","p05e",{}),
("P05",["18"],"C","excecao_omitida",3,"É facultado ao servidor declinar dos prazos de dez a trinta dias estabelecidos para a retomada do exercício em decorrência de remoção, redistribuição, requisição, cessão ou exercício provisório em outro município.","Art. 18, § 2º.","","p05f",{}),
("P05",["17"],"C","conceito_correto",2,"A promoção não interrompe o tempo de exercício, que é contado no novo posicionamento na carreira a partir da data de publicação do ato que promover o servidor.","Art. 17.","","p05g",{}),
("P05",["17"],"E","troca_efeito",2,"A promoção interrompe o tempo de exercício, que passa a ser contado do zero no novo posicionamento na carreira, a partir da data de publicação do ato que promover o servidor, perdendo ele o tempo anterior.","Art. 17: a promoção não interrompe o tempo de exercício.","nega a continuidade","p05g",{}),
("P05",["16"],"C","conceito_correto",1,"O início, a suspensão, a interrupção e o reinício do exercício serão registrados no assentamento individual do servidor.","Art. 16.","","p05h",{}),
# P06
("P06",["19"],"C","troca_numero",2,"Os servidores cumprirão jornada fixada em razão das atribuições do cargo, respeitada a duração máxima de quarenta horas semanais e observados os limites mínimo e máximo de seis e oito horas diárias, respectivamente.","Art. 19, caput.","","p06a",{}),
("P06",["19"],"E","troca_numero",2,"Os servidores cumprirão jornada fixada em razão das atribuições do cargo, respeitada a duração máxima de quarenta e quatro horas semanais e observados os limites mínimo e máximo de quatro e oito horas diárias, respectivamente.","Art. 19: 40 horas semanais; limites diários de 6 e 8 horas.","altera limites","p06a",{}),
("P06",["19"],"C","conceito_correto",2,"O ocupante de cargo em comissão ou função de confiança submete-se a regime de integral dedicação ao serviço, podendo ser convocado sempre que houver interesse da Administração.","Art. 19, § 1º.","","p06b",{}),
("P06",["19"],"E","generalizacao",3,"O limite de quarenta horas semanais aplica-se a todas as carreiras do serviço público federal, inclusive às que possuem duração de trabalho fixada em lei especial.","Art. 19, § 2º: o disposto não se aplica à duração do trabalho estabelecida em leis especiais.","ignora lei especial","p06c",{}),
# P07
("P07",["20"],"C","conceito_correto",2,"Entre os fatores de avaliação do servidor em estágio probatório estão a assiduidade, a disciplina, a capacidade de iniciativa, a produtividade e a responsabilidade.","Art. 20, I a V.","","p07a",{}),
("P07",["20"],"E","confusao_instituto",2,"Entre os fatores de avaliação do servidor em estágio probatório estão a assiduidade, a disciplina, a eficiência, a moralidade e a publicidade, que correspondem aos princípios constitucionais da Administração Pública.","Art. 20, I a V: assiduidade, disciplina, capacidade de iniciativa, produtividade e responsabilidade (eficiência, moralidade e publicidade são princípios do art. 37 da CF).","mistura fatores com princípios","p07a",{}),
("P07",["20"],"C","conceito_correto",3,"A avaliação de desempenho do servidor em estágio probatório será submetida à homologação da autoridade competente quatro meses antes de findo o período, sem prejuízo da continuidade de apuração dos fatores.","Art. 20, § 1º.","","p07b",{}),
("P07",["20"],"E","troca_numero",3,"A avaliação de desempenho do servidor em estágio probatório será submetida à homologação da autoridade competente somente após o término do período, interrompendo-se a apuração dos fatores.","Art. 20, § 1º: homologação quatro meses antes do término do período, sem prejuízo da continuidade de apuração.","altera momento e efeito","p07b",{}),
("P07",["20"],"C","consequencia",2,"O servidor que não for aprovado no estágio probatório será exonerado ou, se estável, reconduzido ao cargo anteriormente ocupado.","Art. 20, § 2º.","","p07c",{}),
("P07",["20"],"E","consequencia",2,"O servidor não aprovado no estágio probatório será sempre demitido, ainda que estável em cargo anteriormente ocupado.","Art. 20, § 2º: exoneração ou, se estável, recondução; demissão é penalidade disciplinar.","confunde exoneração com demissão","p07c",{}),
("P07",["20"],"C","excecao_omitida",3,"Durante o estágio probatório, o servidor poderá exercer cargos de provimento em comissão ou funções de direção, chefia ou assessoramento no órgão ou entidade de lotação, e somente poderá ser cedido a outro órgão para ocupar cargos de Natureza Especial ou cargos DAS de níveis 6, 5 e 4, ou equivalentes.","Art. 20, § 3º.","","p07d",{}),
("P07",["20"],"E","restricao_indevida",3,"Durante o estágio probatório, o servidor não poderá exercer cargos de provimento em comissão ou funções de direção, chefia ou assessoramento no órgão de lotação, nem ser cedido a outro órgão ou entidade, ainda que para ocupar cargos de Natureza Especial ou DAS de níveis 6, 5 e 4.","Art. 20, § 3º: é permitido exercer tais cargos no órgão de lotação e ser cedido para os cargos de Natureza Especial e DAS 6, 5 e 4.","veda o que a lei permite","p07d",{}),
("P07",["20"],"C","troca_efeito",3,"O estágio probatório fica suspenso durante algumas licenças e afastamentos previstos na lei, sendo retomado a partir do término do impedimento.","Art. 20, § 5º.","","p07e",{}),
("P07",["20"],"E","troca_efeito",3,"As licenças e afastamentos concedidos durante o estágio probatório não têm qualquer efeito sobre a contagem do período, que corre normalmente.","Art. 20, § 5º: o estágio fica suspenso nas licenças e afastamentos ali previstos, e é retomado ao término do impedimento.","nega a suspensão","p07e",{}),
("P07",["20","21"],"C","caso_concreto",3,"Sob a óptica constitucional, o servidor nomeado para cargo efetivo adquire estabilidade após três anos de efetivo exercício, de modo que o prazo de dois anos, ainda constante do art. 21 da Lei n.º 8.112/1990, foi superado pela EC n.º 19/1998.","CF, art. 41, caput (EC 19/98): três anos; o art. 21 da lei, em sua redação original, fixava dois anos.","","p07f",CJ),
("P07",["20","21"],"E","caso_concreto",3,"Conforme a Lei n.º 8.112/1990 e a Constituição Federal vigentes, o servidor ocupante de cargo efetivo adquire estabilidade após dois anos de efetivo exercício, ao término do estágio probatório de vinte e quatro meses.","A CF, art. 41 (EC 19/98), exige três anos de efetivo exercício; prevalece sobre os dois anos do art. 21 e os 24 meses do art. 20.","aplica prazo superado","p07f",CJ),
("P07",["22"],"C","conceito_correto",2,"O servidor estável só perderá o cargo em virtude de sentença judicial transitada em julgado ou de processo administrativo disciplinar no qual lhe seja assegurada ampla defesa.","Art. 22; CF, art. 41, § 1º.","","p07g",{}),
("P07",["22"],"E","restricao_indevida",2,"O servidor estável pode perder o cargo por decisão judicial, ainda que sujeita a recurso, ou por processo administrativo disciplinar em que seja assegurada a ampla defesa.","Art. 22: só em virtude de sentença judicial transitada em julgado ou de PAD com ampla defesa.","dispensa o trânsito em julgado","p07g",{}),
# P08
("P08",["24"],"C","conceito_correto",2,"Readaptação é a investidura do servidor em cargo de atribuições e responsabilidades compatíveis com a limitação que tenha sofrido em sua capacidade física ou mental, verificada em inspeção médica.","Art. 24, caput.","","p08a",{}),
("P08",["24"],"E","confusao_instituto",2,"Readaptação é a investidura do servidor aposentado por invalidez em cargo de atribuições compatíveis, quando a junta médica oficial declarar insubsistentes os motivos da aposentadoria, retornando ele à atividade.","Esse é o conceito de reversão (art. 25); readaptação é a investidura em cargo compatível com a limitação.","troca readaptação por reversão","p08a",{}),
("P08",["24"],"C","excecao_omitida",3,"A readaptação será efetivada em cargo de atribuições afins, respeitados a habilitação exigida, o nível de escolaridade e a equivalência de vencimentos; não havendo cargo vago, o servidor exercerá suas atribuições como excedente até a ocorrência de vaga.","Art. 24, § 2º.","","p08b",{}),
("P08",["24"],"E","troca_efeito",3,"A readaptação será efetivada em cargo de atribuições afins, respeitados a habilitação exigida e o nível de escolaridade, podendo importar redução de vencimentos; não havendo cargo vago, o servidor aguardará em disponibilidade até a ocorrência de vaga.","Art. 24, § 2º: exige equivalência de vencimentos; sem vaga, exerce atribuições como excedente.","admite redução e disponibilidade","p08b",{}),
("P08",["24"],"C","consequencia",2,"Se o readaptando for julgado incapaz para o serviço público, será aposentado.","Art. 24, § 1º.","","p08c",{}),
("P08",["27"],"C","troca_numero",1,"Não poderá reverter o aposentado que já tiver completado setenta anos de idade.","Art. 27.","","p08d",{}),
("P08",["27"],"E","troca_numero",1,"Não poderá reverter o aposentado que já tiver completado sessenta e cinco anos de idade.","Art. 27: setenta anos.","altera idade-limite","p08d",{}),
("P08",["25"],"C","conceito_correto",2,"Reversão é o retorno à atividade de servidor aposentado.","Art. 25, caput.","","p08e",{}),
("P08",["25"],"E","conceito_correto",2,"Reversão é o retorno do servidor estável ao cargo anteriormente ocupado, decorrente de inabilitação em estágio probatório relativo a outro cargo.","Esse é o conceito de recondução (art. 29, I).","troca reversão por recondução","p08e",{}),
# P09
("P09",["28"],"C","conceito_correto",2,"A reintegração é a reinvestidura do servidor estável no cargo anteriormente ocupado, ou no cargo resultante de sua transformação, quando invalidada a sua demissão por decisão administrativa ou judicial, com ressarcimento de todas as vantagens.","Art. 28, caput.","","p09a",{}),
("P09",["28"],"E","troca_efeito",2,"A reintegração é a reinvestidura do servidor estável no cargo anteriormente ocupado, ou no cargo resultante de sua transformação, quando invalidada a sua demissão por decisão judicial, sem ressarcimento das vantagens do período de afastamento, que dependem de nova decisão.","Art. 28: a reintegração se dá com ressarcimento de todas as vantagens.","nega ressarcimento","p09a",{}),
("P09",["28"],"C","caso_concreto",3,"Reintegrado servidor estável cujo cargo original encontra-se provido por outro ocupante, esse ocupante será reconduzido ao cargo de origem, sem direito a indenização, ou aproveitado em outro cargo, ou ainda posto em disponibilidade.","Art. 28, § 2º.","","p09b",{}),
("P09",["28"],"E","caso_concreto",3,"Reintegrado servidor estável cujo cargo original encontra-se provido por outro ocupante, esse ocupante será exonerado de ofício, com direito a indenização, ou posto em disponibilidade, a critério da Administração.","Art. 28, § 2º: recondução sem indenização, aproveitamento ou disponibilidade.","troca consequência","p09b",{}),
("P09",["28"],"C","consequencia",2,"Se o cargo ocupado pelo servidor reintegrado tiver sido extinto, ele ficará em disponibilidade.","Art. 28, § 1º.","","p09c",{}),
("P09",["29"],"C","conceito_correto",2,"A recondução é o retorno do servidor estável ao cargo anteriormente ocupado e decorrerá de inabilitação em estágio probatório relativo a outro cargo ou de reintegração do anterior ocupante.","Art. 29, I e II.","","p09d",{}),
("P09",["29"],"E","restricao_indevida",2,"A recondução decorre exclusivamente da reintegração do anterior ocupante do cargo, não se aplicando ao servidor inabilitado em estágio probatório de outro cargo.","Art. 29: decorre de inabilitação em estágio probatório (I) ou de reintegração do anterior ocupante (II).","exclui hipótese","p09d",{}),
("P09",["30","31"],"C","conceito_correto",2,"O retorno à atividade de servidor em disponibilidade far-se-á mediante aproveitamento obrigatório em cargo de atribuições e vencimentos compatíveis com o anteriormente ocupado.","Art. 30.","","p09e",{}),
("P09",["30"],"E","troca_efeito",2,"O aproveitamento de servidor em disponibilidade é ato discricionário da Administração, que pode optar por não aproveitá-lo se não houver conveniência.","Art. 30: o aproveitamento é obrigatório.","torna discricionário","p09e",{}),
("P09",["32"],"C","excecao_omitida",3,"Será tornado sem efeito o aproveitamento e cassada a disponibilidade se o servidor não entrar em exercício no prazo legal, salvo doença comprovada por junta médica oficial.","Art. 32.","","p09f",{}),
# P10
("P10",["33"],"C","conceito_correto",1,"A vacância do cargo público decorrerá, entre outras hipóteses, de exoneração, demissão, promoção, readaptação, aposentadoria, posse em outro cargo inacumulável e falecimento.","Art. 33.","","p10a",{}),
("P10",["33"],"E","confusao_instituto",1,"A vacância do cargo público decorrerá, entre outras hipóteses, de reintegração, recondução, aproveitamento, reversão e nomeação em caráter efetivo, ao lado do falecimento do ocupante.","Art. 33: reintegração, recondução, aproveitamento, reversão e nomeação são formas de provimento (art. 8º), não causas de vacância.","confunde provimento com vacância","p10a",{}),
("P10",["34"],"C","conceito_correto",2,"A exoneração de cargo efetivo dar-se-á a pedido do servidor ou de ofício, sendo de ofício quando não satisfeitas as condições do estágio probatório ou quando, tendo tomado posse, o servidor não entrar em exercício no prazo estabelecido.","Art. 34, caput e parágrafo único.","","p10b",{}),
("P10",["34"],"E","restricao_indevida",2,"A exoneração de cargo efetivo somente pode ocorrer a pedido do servidor, sendo vedada a exoneração de ofício, mesmo quando não satisfeitas as condições do estágio probatório ou quando, tendo tomado posse, o servidor não entrar em exercício no prazo.","Art. 34: a exoneração de cargo efetivo dar-se-á a pedido ou de ofício.","veda exoneração de ofício","p10b",{}),
("P10",["35"],"C","conceito_correto",2,"A exoneração de cargo em comissão e a dispensa de função de confiança dar-se-ão a juízo da autoridade competente ou a pedido do próprio servidor.","Art. 35, I e II.","","p10c",{}),
("P10",["35"],"E","troca_efeito",2,"A exoneração de ocupante de cargo em comissão depende de prévio processo administrativo no qual lhe seja assegurada ampla defesa.","Art. 35, I: dá-se a juízo da autoridade competente (livre exoneração), sem necessidade de processo.","exige processo","p10c",{}),
# P11
("P11",["36"],"C","conceito_correto",2,"Remoção é o deslocamento do servidor, a pedido ou de ofício, no âmbito do mesmo quadro, com ou sem mudança de sede.","Art. 36, caput.","","p11a",{}),
("P11",["36","37"],"E","confusao_instituto",2,"Redistribuição é o deslocamento do servidor, a pedido ou de ofício, no âmbito do mesmo quadro, com ou sem mudança de sede.","Esse é o conceito de remoção (art. 36); a redistribuição desloca o cargo para outro órgão ou entidade do mesmo Poder (art. 37).","troca remoção por redistribuição","p11a",{}),
("P11",["37"],"C","conceito_correto",2,"Redistribuição é o deslocamento de cargo de provimento efetivo, ocupado ou vago, no âmbito do quadro geral de pessoal, para outro órgão ou entidade do mesmo Poder, com prévia apreciação do órgão central do SIPEC.","Art. 37, caput.","","p11b",{}),
("P11",["37"],"E","troca_autoridade",2,"Redistribuição é o deslocamento de servidor ocupante de cargo efetivo para órgão ou entidade de Poder diverso, no âmbito do quadro geral de pessoal, dispensada a apreciação do órgão central do SIPEC.","Art. 37: para outro órgão ou entidade do mesmo Poder, com prévia apreciação do órgão central do SIPEC.","troca Poder e autoridade","p11b",{}),
("P11",["37"],"C","conceito_correto",3,"A redistribuição ocorrerá ex officio para ajustamento de lotação e da força de trabalho às necessidades dos serviços, inclusive nos casos de reorganização, extinção ou criação de órgão ou entidade.","Art. 37, § 1º.","","p11c",{}),
("P11",["38"],"C","conceito_correto",2,"Os servidores investidos em cargo ou função de direção ou chefia e os ocupantes de cargo de Natureza Especial terão substitutos indicados no regimento interno ou, no caso de omissão, previamente designados pelo dirigente máximo do órgão ou entidade.","Art. 38, caput.","","p11d",{}),
("P11",["38"],"C","troca_numero",3,"O substituto fará jus à retribuição pelo exercício do cargo de direção ou chefia nos casos de afastamentos ou impedimentos legais do titular superiores a trinta dias consecutivos, paga na proporção dos dias de efetiva substituição que excederem esse período.","Art. 38, § 2º.","","p11e",{}),
("P11",["38"],"E","troca_numero",3,"O substituto fará jus à retribuição pelo exercício do cargo de direção ou chefia desde o primeiro dia de afastamento ou impedimento legal do titular, paga na proporção dos dias de efetiva substituição, independentemente da duração do afastamento.","Art. 38, § 2º: a retribuição é devida nos afastamentos superiores a trinta dias consecutivos, pelos dias que excederem esse período.","elimina o limite de 30 dias","p11e",{}),
]
